sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-30: "FLEET - Validate Reservation Request" - runs V1-V7 (FleetReservationValidator)
    var state = current.getValue('reservation_state');
    var isInsert = current.operation() == 'insert';
    var inScope = state == 'DRAFT' || state == 'PENDING_APPROVAL' ||
        (isInsert && state == 'PENDING_ASSIGNMENT' && !current.replaces_reservation.nil());
    if (!inScope) {
        return;
    }
    var fields = ['start_datetime', 'end_datetime', 'vehicle_category', 'requested_depot', 'assigned_driver', 'requested_by', 'assigned_vehicle', 'reservation_state'];
    var changed = isInsert;
    for (var i = 0; i < fields.length && !changed; i++) {
        changed = current[fields[i]].changes();
    }
    if (!changed) {
        return;
    }
    var errors = new FleetReservationValidator().validate(current);
    if (errors.length) {
        for (var j = 0; j < errors.length; j++) {
            gs.addErrorMessage(errors[j]);
        }
        current.setAbortAction(true);
    }
})(current, previous);
